column2:
node --input-type=module <<'JS'
import {defineAdapter,createIRArtifact,openIR} from './dist/framework/ir/index.js';
import {defineIR,differential,runDifferential,differentialSpec} from './dist/framework/contracts/index.js';
import {applyPass,definePass} from './dist/framework/passes/index.js';
const meta={id:'t.probe',version:'1',description:'probe',validate(x){if(x.n!==1)throw Error()}};
const ir=defineIR(meta), adapter=defineAdapter({...meta,kind:ir.kind,schemaVersion:ir.schemaVersion,entities:()=>[],resolve:()=>undefined,relations:()=>[],describe:()=>'',relationKinds:{}});
const a=createIRArtifact(adapter,'probe',{n:1});
const inv=differential({id:'probe.check',version:'1',description:'probe',inputs:{origin:ir,candidate:ir},baseline:'origin',subject:'candidate',count:1,cases:()=>[0],run:(_,v)=>v.value.n,compare:(a,b)=>a===b});
console.log(runDifferential(differentialSpec(inv),{origin:a,candidate:a}).status);
const pass=definePass({id:'probe.pass',version:'1',description:'probe',adapter,ir,writes:{entities:[],relations:[]},run:()=>({native:a.value})});
const p=applyPass(pass,a,{manager:{}});console.log(p instanceof Promise); try{await p}catch(e){console.log(e.message)}
JS

